#include "VoiceFit.h"
#include <iostream>
#include <stdexcept>
#include <cmath>
namespace {void check(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}vocal::PitchAnalysis melody(double low,double high){vocal::PitchAnalysis a;a.monophonic=true;for(int note=static_cast<int>(low);note<=static_cast<int>(high);++note)for(int i=0;i<15;++i)a.frames.push_back({a.frames.size()*.02,static_cast<double>(note),.99,.1});return a;}}
int main(){try{auto voice=melody(45,65);auto profile=vocal::measureComfortableRange(voice);check(profile.valid&&profile.lowMidi>=45&&profile.highMidi<=65,"measure comfortable singing range");vocal::VoiceProfile manual{true,45,65,55,0};auto song=melody(60,79);auto fit=vocal::fitSongToVoice(manual,song);std::cout<<"fit: beat "<<fit.semitones<<" st, singing octave "<<fit.singingOctaves<<" -> "<<fit.targetLow<<".."<<fit.targetHigh<<"\n";check(fit.valid&&fit.fits&&fit.semitones==-2&&fit.singingOctaves==-1,"transpose music to singer range with octave-aware melody");auto noShift=vocal::fitSongToVoice({true,43,62,52,0},melody(55,74));check(noShift.fits&&noShift.semitones==0&&noShift.singingOctaves==-1,"avoid changing beat if octave choice alone fits voice");auto impossible=vocal::fitSongToVoice({true,48,60,54,0},melody(40,80));check(impossible.valid&&!impossible.fits,"do not claim a wide melody fits a narrow voice range");auto note=melody(60,60);check(!vocal::measureComfortableRange(note).valid,"a single note cannot identify singer range");auto noisy=voice;for(auto& f:noisy.frames)f.confidence=.3;check(!vocal::measureComfortableRange(noisy).valid,"reject unclear voice calibration");voice.clippedFraction=.02;check(!vocal::measureComfortableRange(voice).valid,"reject heavily clipped calibration");song.monophonic=false;check(!vocal::fitSongToVoice(manual,song).valid,"never use beat bass notes as vocal melody range");manual.valid=false;check(!vocal::fitSongToVoice(manual,melody(60,79)).valid,"no automatic fit without personal voice profile");std::cout<<"PASS: personal range, octave-aware song fit, minimal beat shift and invalid-data rejection\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 1;}}
